#include <iostream>
#include <vector>
#include <cstdint>
using namespace std;

using ll = long long;

ll read() {
    ll value = 0;
    char c = getchar();
    while (c < '0' || c > '9') c = getchar();
    while (c >= '0' && c <= '9') {
        value = value * 10 + (c - '0');
        c = getchar();
    }
    return value;
}

int main() {
    int n = static_cast<int>(read());
    int m = static_cast<int>(read());
    int a = static_cast<int>(read());
    int b = static_cast<int>(read());

    ll current = read();
    ll x = read();
    ll y = read();
    ll z = read();

    const int width = m - b + 1;
    vector<ll> horizontal(static_cast<size_t>(n) * width);
    vector<int> dequeIndex(m);
    vector<ll> dequeValue(m);

    for (int row = 0; row < n; ++row) {
        int head = 0, tail = 0;

        for (int col = 0; col < m; ++col) {
            ll value = current;
            current = static_cast<ll>(
                (static_cast<__int128>(current) * x + y) % z
            );

            while (head < tail && dequeValue[tail - 1] >= value) {
                --tail;
            }

            dequeIndex[tail] = col;
            dequeValue[tail] = value;
            ++tail;

            while (head < tail && dequeIndex[head] <= col - b) {
                ++head;
            }

            if (col >= b - 1) {
                horizontal[static_cast<size_t>(row) * width + col - b + 1] =
                    dequeValue[head];
            }
        }
    }

    ll answer = 0;
    vector<int> rowDeque(n);

    for (int col = 0; col < width; ++col) {
        int head = 0, tail = 0;

        for (int row = 0; row < n; ++row) {
            while (head < tail && rowDeque[head] <= row - a) {
                ++head;
            }

            ll value = horizontal[static_cast<size_t>(row) * width + col];

            while (head < tail &&
                   horizontal[static_cast<size_t>(rowDeque[tail - 1]) * width + col] >= value) {
                --tail;
            }

            rowDeque[tail++] = row;

            if (row >= a - 1) {
                answer += horizontal[
                    static_cast<size_t>(rowDeque[head]) * width + col
                ];
            }
        }
    }

    cout << answer;
    return 0;
}

