using namespace std;

using ll = long long;

ll read() {
    ll value = 0;
    int c = getchar();
    while (c < '0' || c > '9') c = getchar();
    while (c >= '0' && c <= '9') {
        value = value * 10 + (c - '0');
        c = getchar();
    }
    return value;
}

int main() {
    int n = static_cast<int>(read());
    int m = static_cast<int>(read());
    int a = static_cast<int>(read());
    int b = static_cast<int>(read());

    ll current = read();
    ll x = read();
    ll y = read();
    ll z = read();

    const int width = m - b + 1;
    vector<ll> horizontal(static_cast<size_t>(n) * width);
    deque<pair<int, ll>> q;

    for (int i = 0; i < n; ++i) {
        q.clear();

        for (int j = 0; j < m; ++j) {
            ll value = current;
            current = static_cast<ll>(
                (static_cast<__int128>(current) * x + y) % z
            );

            while (!q.empty() && q.back().second >= value)
                q.pop_back();
            q.emplace_back(j, value);

            while (!q.empty() && q.front().first <= j - b)
                q.pop_front();

            if (j >= b - 1)
                horizontal[static_cast<size_t>(i) * width + j - b + 1]
                    = q.front().second;
        }
    }

    ll answer = 0;

    for (int col = 0; col < width; ++col) {
        q.clear();

        for (int row = 0; row < n; ++row) {
            ll value = horizontal[static_cast<size_t>(row) * width + col];

            while (!q.empty() && q.back().second >= value)
                q.pop_back();
            q.emplace_back(row, value);

            while (!q.empty() && q.front().first <= row - a)
                q.pop_front();

            if (row >= a - 1)
                answer += q.front().second;
        }
    }

    cout << answer;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using u64 = uint64_t;
using u128 = __uint128_t;

template <typename T>
u128 solve(int n, int m, int a, int b, u64 g0, u64 x, u64 y, u64 z) {
    const int width = m - b + 1;
    vector<T> horizontal(static_cast<size_t>(n) * width);
    vector<T> queueValue(m);
    vector<int> queueIndex(max(n, m));

    u64 current = g0;

    for (int i = 0; i < n; ++i) {
        int head = 0, tail = 0;

        for (int j = 0; j < m; ++j) {
            T value = static_cast<T>(current);

            while (head < tail && queueValue[tail - 1] >= value)
                --tail;

            queueValue[tail] = value;
            queueIndex[tail] = j;
            ++tail;

            while (head < tail && queueIndex[head] <= j - b)
                ++head;

            if (j >= b - 1)
                horizontal[static_cast<size_t>(i) * width + j - b + 1] =
                    queueValue[head];

            current = static_cast<u64>(
                (static_cast<u128>(current) * x + y) % z
            );
        }
    }

    u128 answer = 0;

    for (int column = 0; column < width; ++column) {
        int head = 0, tail = 0;

        for (int row = 0; row < n; ++row) {
            T value = horizontal[static_cast<size_t>(row) * width + column];

            while (head < tail &&
                   horizontal[static_cast<size_t>(queueIndex[tail - 1]) * width +
                              column] >= value)
                --tail;

            queueIndex[tail++] = row;

            while (head < tail && queueIndex[head] <= row - a)
                ++head;

            if (row >= a - 1) {
                answer += horizontal[
                    static_cast<size_t>(queueIndex[head]) * width + column
                ];
            }
        }
    }

    return answer;
}

void printUnsigned128(u128 value) {
    if (value == 0) {
        cout << '0';
        return;
    }

    string result;
    while (value > 0) {
        result.push_back(char('0' + value % 10));
        value /= 10;
    }
    reverse(result.begin(), result.end());
    cout << result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, a, b;
    u64 g0, x, y, z;
    cin >> n >> m >> a >> b >> g0 >> x >> y >> z;

    u128 answer;
    if (g0 <= UINT32_MAX && z - 1 <= UINT32_MAX)
        answer = solve<uint32_t>(n, m, a, b, g0, x, y, z);
    else
        answer = solve<uint64_t>(n, m, a, b, g0, x, y, z);

    printUnsigned128(answer);
    return 0;
}

